const server = new McpServer({ name: "kynth-core", version: "0.5.0" });

/** Wrap an SDK call so any KynthError becomes a clean MCP tool error. */
async function run<T>(fn: () => Promise<T>) {
  try {
    const result = await fn();
    return { content: [{ type: "text" as const, text: JSON.stringify(result, null, 2) }] };
  } catch (err) {
    const message =
      err instanceof KynthError
        ? `Kynth Core error [${err.code}] (HTTP ${err.status}): ${err.message}`
        : err instanceof Error
          ? err.message
          : "Unknown error";
    return { content: [{ type: "text" as const, text: message }], isError: true };
  }
}

// A document input for the multimodal tools. Provide exactly one source.
const docFields = {
  fileUrl: z.string().url().optional().describe("Public URL to a PDF or image."),
  text: z.string().optional().describe("Raw text, if you already have it."),
  fileBase64: z.string().optional().describe("Base64-encoded file bytes (with fileMimeType)."),
  fileMimeType: z.string().optional().describe("MIME type for fileBase64, e.g. application/pdf."),
};

/** Resolve the doc-input fields into the SDK's DocumentInput union. */
function toDoc(a: { fileUrl?: string; text?: string; fileBase64?: string; fileMimeType?: string }) {
  if (a.fileUrl) return { fileUrl: a.fileUrl };
  if (a.fileBase64 && a.fileMimeType) return { file: { data: a.fileBase64, mimeType: a.fileMimeType } };
  if (a.text) return { text: a.text };
  throw new Error("Provide one of: fileUrl, text, or fileBase64 + fileMimeType.");
}

/**
 * Tool annotations. The Claude Connectors Directory requires every tool to
 * declare a title plus the applicable hints; missing annotations are the single
 * largest cause of submission rejection.
 *
 * Every Kynth Core capability tool has the same shape: it calls the hosted API,
 * debits the account's credit wallet, and returns a result. It never mutates the
 * caller's data, and nothing it does is irreversible — but it is NOT read-only,
 * because the wallet balance changes, and NOT idempotent, because a repeat call
 * is charged again.
 */
const CORE_TOOL: ToolAnnotations = {
  readOnlyHint: false,
  destructiveHint: false,
  idempotentHint: false,
  openWorldHint: true,
};

/** Reading your own balance costs nothing and changes nothing. */
const ACCOUNT_TOOL: ToolAnnotations = {
  readOnlyHint: true,
  destructiveHint: false,
  idempotentHint: true,
  openWorldHint: true,
};

